CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','viewer')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE projects (id uuid PRIMARY KEY, name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations (id uuid PRIMARY KEY, kind text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'UNCONFIGURED', error text, last_checked timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sources (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), kind text NOT NULL, name text NOT NULL, configuration jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,kind,name));
CREATE TABLE repositories (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), full_name text NOT NULL, branch text NOT NULL DEFAULT 'main', track_commits boolean NOT NULL DEFAULT false, stable_only boolean NOT NULL DEFAULT true, etag text, data jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PENDING', last_checked timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,full_name));
CREATE TABLE images (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), reference text NOT NULL, registry text NOT NULL, digest text, metadata jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PENDING', last_checked timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,reference));
CREATE TABLE image_versions (id uuid PRIMARY KEY, image_id uuid NOT NULL REFERENCES images(id), tag text NOT NULL, digest text NOT NULL, architecture jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(image_id,tag,digest));
CREATE TABLE deployments (id uuid PRIMARY KEY, project_id uuid REFERENCES projects(id), source text NOT NULL, server text NOT NULL, namespace text NOT NULL DEFAULT '', container text NOT NULL, environment text NOT NULL DEFAULT 'unknown', image text NOT NULL, digest text, running boolean NOT NULL DEFAULT false, last_seen timestamptz NOT NULL DEFAULT now(), UNIQUE(source,server,namespace,container));
CREATE TABLE scan_runs (id uuid PRIMARY KEY, image_id uuid NOT NULL REFERENCES images(id), digest text, source text NOT NULL DEFAULT 'trivy', status text NOT NULL CHECK(status IN ('RUNNING','COMPLETED','FAILED')), scanner_version text, database_metadata jsonb NOT NULL DEFAULT '{}', error text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, duration_seconds double precision);
CREATE INDEX scans_image_time ON scan_runs(image_id,started_at DESC);
CREATE TABLE sbom_artifacts (id uuid PRIMARY KEY, scan_run_id uuid NOT NULL REFERENCES scan_runs(id), format text NOT NULL, object_key text, sha256 text NOT NULL, document jsonb NOT NULL, storage_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scan_run_id,format));
CREATE TABLE vulnerabilities (id text PRIMARY KEY, title text NOT NULL DEFAULT '', severity text NOT NULL, epss double precision CHECK(epss BETWEEN 0 AND 1), kev boolean NOT NULL DEFAULT false, enriched_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vulnerability_findings (id uuid PRIMARY KEY, vulnerability_id text NOT NULL REFERENCES vulnerabilities(id), scan_run_id uuid NOT NULL REFERENCES scan_runs(id), image_id uuid NOT NULL REFERENCES images(id), package text NOT NULL, installed_version text NOT NULL, fixed_version text NOT NULL DEFAULT '', target text NOT NULL DEFAULT '', severity text NOT NULL, status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','IN_PROGRESS','PENDING_VERIFICATION','FIXED','RISK_ACCEPTED','FALSE_POSITIVE')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scan_run_id,vulnerability_id,package,installed_version,target));
CREATE INDEX findings_image ON vulnerability_findings(image_id);
CREATE INDEX findings_cve ON vulnerability_findings(vulnerability_id);
CREATE TABLE vulnerability_status_history (id uuid PRIMARY KEY, finding_id uuid NOT NULL REFERENCES vulnerability_findings(id), old_status text NOT NULL, new_status text NOT NULL, user_id uuid REFERENCES users(id), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE update_recommendations (id uuid PRIMARY KEY, image_id uuid NOT NULL REFERENCES images(id), candidate text NOT NULL, digest text, status text NOT NULL CHECK(status IN ('UP_TO_DATE','UPDATE_AVAILABLE','SECURITY_FIX_AVAILABLE','TESTING','APPROVED','DEPLOYED','OUTDATED','UNKNOWN')), major_warning boolean NOT NULL DEFAULT false, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE version_approvals (id uuid PRIMARY KEY, image_id uuid NOT NULL REFERENCES images(id), version text NOT NULL, digest text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), environment text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(image_id,digest,environment));
CREATE TABLE notification_rules (id uuid PRIMARY KEY, event text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT true, minimum_severity text NOT NULL DEFAULT 'HIGH', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY, event_key text NOT NULL UNIQUE, event text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE jobs (id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, dedup_key text, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','COMPLETED','FAILED')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE UNIQUE INDEX jobs_active_dedup ON jobs(dedup_key) WHERE status IN ('PENDING','RUNNING');
CREATE INDEX jobs_claim ON jobs(run_at) WHERE status IN ('PENDING','RUNNING');
CREATE TABLE audit_logs (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, resource text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_time ON audit_logs(created_at DESC);
